// Local versioned saves, bounded history, validation and explicit restore preview.
const SAVE_KEY='ashen-v1',HISTORY_KEY='ashen-history-v1',SAVE_VERSION=3;
let saveStatus='未保存',saveLastError='',savePending=null,saveMenuOpen=false,saveTimer=30;
function saveHash(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16).padStart(8,'0')}
function saveNumber(n,label,min=-1e9,max=1e9){if(typeof n!=='number'||!Number.isFinite(n)||n<min||n>max)throw Error(label+'の数値が不正です');return n}
function saveGem(g){if(!g||typeof g!=='object'||!Object.hasOwn(GEM,g.type))throw Error('不明なジェムがあります');return{type:g.type,level:saveNumber(g.level,'ジェムレベル',1,20),xp:saveNumber(g.xp,'ジェム経験値',0)}}
function saveItem(it,expected){if(it===null||it===undefined)return null;if(!it||typeof it!=='object'||!Object.hasOwn(EQUIPMENT,it.slot)||expected&&it.slot!==expected)throw Error('装備部位が不正です');if(typeof it.name!=='string'||it.name.length>80)throw Error('装備名が不正です');let result={slot:it.slot,name:it.name,value:saveNumber(it.value,'装備基礎値',0),color:['','blue','gold'].includes(it.color)?it.color:'',rarity:['normal','magic','rare'].includes(it.rarity)?it.rarity:'normal'};
 result.locked=it.locked===true;
 if(it.mods!==undefined){if(!Array.isArray(it.mods)||it.mods.length>12)throw Error('装備効果が不正です');result.mods=it.mods.map(m=>{if(!m||!Object.hasOwn(MODS,m.key))throw Error('不明な装備効果です');return{key:m.key,value:saveNumber(m.value,'装備効果',0)}})}
 if(it.sockets!==undefined){if(!Array.isArray(it.sockets)||it.sockets.length>6)throw Error('ソケットが不正です');result.sockets=it.sockets.map(s=>{if(!s||!Object.hasOwn(COLORS,s.color))throw Error('ソケット色が不正です');return{color:s.color,gem:s.gem?saveGem(s.gem):null}});if(!Array.isArray(it.links)||it.links.length!==Math.max(0,it.sockets.length-1)||it.links.some(v=>typeof v!=='boolean'))throw Error('リンクが不正です');result.links=[...it.links]}
 return result}
function validateSave(data){if(!data||typeof data!=='object'||!data.p||typeof data.p!=='object')throw Error('セーブ形式が違います');let src=data.p,out={};for(let key of ['x','y','level','xp','gold','points','power','vitality','focus','hp','mp','flasks','type'])out[key]=saveNumber(src[key],key);if(!Number.isInteger(out.level)||out.level<1||out.type<0||out.type>2||out.gold<0||out.points<0||out.xp<0)throw Error('キャラクター情報が不正です');let depth=saveNumber(data.floor,'深度',1,100000);if(!Number.isInteger(depth))throw Error('深度が不正です');
 for(let key of ['worldSeed','buildVersion'])if(src[key]!==undefined)out[key]=saveNumber(src[key],key,0,Number.MAX_SAFE_INTEGER);
 if(!Array.isArray(src.bag)||src.bag.length>20)throw Error('鞄が不正です');out.bag=src.bag.map(it=>{let v=saveItem(it);if(!v)throw Error('鞄に空の装備があります');return v});for(let slot of GEAR_SLOTS)out[slot]=saveItem(src[slot],slot);
 if(src.stash!==undefined){if(!Array.isArray(src.stash)||src.stash.length>100)throw Error('倉庫が不正です');out.stash=src.stash.map(it=>{let v=saveItem(it);if(!v)throw Error('倉庫に空の装備があります');return v})}else out.stash=[];
 if(src.gems!==undefined){if(!Array.isArray(src.gems)||src.gems.length>20000)throw Error('ジェム一覧が不正です');out.gems=src.gems.map(saveGem)}
 if(src.nodes!==undefined){if(!Array.isArray(src.nodes)||src.nodes.some(n=>!Number.isInteger(n)||!NODES[n]))throw Error('パッシブが不正です');out.nodes=[...new Set(src.nodes)];if(!out.nodes.includes(0))throw Error('開始パッシブがありません')}
 if(src.bindings!==undefined){if(!Array.isArray(src.bindings)||src.bindings.length>6||src.bindings.some(t=>t!==''&&(!Object.hasOwn(GEM,t)||GEM[t].kind!=='active')))throw Error('スキル割り当てが不正です');out.bindings=[...src.bindings]}
 if(src.expedition!==undefined){let e=src.expedition;if(!e||e.floor!==depth||!Array.isArray(e.seals)||e.seals.length>3||e.seals.some(id=>![2,6,7].includes(id))||new Set(e.seals).size!==e.seals.length)throw Error('封印の進行が不正です');out.expedition={floor:depth,seals:[...e.seals]}}
 if(src.tutorial){let step=saveNumber(src.tutorial.step,'練習の進行',0,LESSONS.length-1);if(!Number.isInteger(step))throw Error('練習の進行が不正です');out.tutorial={step,active:!!src.tutorial.active}}out.tutorialGearGiven=!!src.tutorialGearGiven;return{p:out,floor:depth}}
function encodeSave(data){let clean=validateSave(data),raw=JSON.stringify(clean);return JSON.stringify({schemaVersion:SAVE_VERSION,savedAt:Date.now(),checksum:saveHash(raw),...clean})}
function decodeSave(raw){if(typeof raw!=='string'||raw.length>6000000)throw Error('セーブが空、または大きすぎます');let data;try{data=JSON.parse(raw)}catch{throw Error('JSONを読み取れません')};if(data?.schemaVersion!==undefined){if(data.schemaVersion!==SAVE_VERSION)throw Error('この版では読み込めないセーブです');if(data.checksum!==saveHash(JSON.stringify({p:data.p,floor:data.floor})))throw Error('データの整合性を確認できません')}return{...validateSave(data),savedAt:Number.isFinite(data.savedAt)?data.savedAt:0}}
function saveHistory(){try{let list=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');return Array.isArray(list)?list.filter(e=>e&&typeof e.raw==='string').slice(0,5):[]}catch{return[]}}
function validHistory(){return saveHistory().flatMap(e=>{try{return[{...e,data:decodeSave(e.raw)}]}catch{return[]}})}
function saveCheckpoint(raw,reason){decodeSave(raw);let list=saveHistory();if(list[0]?.raw===raw)return;list.unshift({raw,reason,at:Date.now()});localStorage.setItem(HISTORY_KEY,JSON.stringify(list.slice(0,5)))}
function refreshSaveBadge(){let el=$('saveBadge');if(el){el.textContent=saveStatus;el.classList.toggle('save-error',!!saveLastError);el.title=saveLastError||'保存・バックアップを開く'}}
save=()=>{if(!p||!started)return false;try{let raw=encodeSave({p,floor}),old=localStorage.getItem(SAVE_KEY);if(old&&old!==raw){try{let previous=decodeSave(old),history=saveHistory();if(!history.length||Date.now()-(history[0].at||0)>60000)saveCheckpoint(old,'自動バックアップ')}catch{}}localStorage.setItem(SAVE_KEY,raw);saveStatus='保存済み';saveLastError='';refreshSaveBadge();return true}catch(error){saveStatus='保存できません';saveLastError=error.message||'保存領域を確認してください';refreshSaveBadge();return false}};
function loadSaveData(data){p=data.p;floor=data.floor;started=true;dead=false;selectedGem=null;inventoryNav.open=false;tutorialGuideOpen=false;saveMenuOpen=false;migrate();enterFloor();closePanel();if(p.tutorial?.active)tutorialShow();return true}
resume=()=>{try{let raw=localStorage.getItem(SAVE_KEY),data;try{data=decodeSave(raw)}catch(error){let backup=validHistory()[0];if(!backup)throw error;data=backup.data;loadSaveData(data);say('直近の正常なバックアップから復旧しました');return}loadSaveData(data)}catch(error){saveLastError=error.message;saveStatus='復旧が必要';showSaveManager('保存を開けませんでした：'+error.message)}};
function saveBackupNow(){if(!started||!save()){showSaveManager('保存に失敗しました。JSON書き出しで手元に保管できます。');return}try{saveCheckpoint(localStorage.getItem(SAVE_KEY),'手動バックアップ');showSaveManager('現在の状態をバックアップしました')}catch(e){showSaveManager('バックアップに失敗しました：'+e.message)}}
function exportSave(){try{let raw=started?encodeSave({p,floor}):localStorage.getItem(SAVE_KEY);decodeSave(raw);let blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='ashen-depths-save-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);let field=$('saveText');if(field)field.value=raw;saveMessage('JSONを書き出しました。下の欄からコピーして保管することもできます。')}catch(e){saveMessage('書き出せません：'+e.message)}}
function saveMessage(message){let el=$('saveMessage');if(el)el.textContent=message}
async function readSaveFile(input){let file=input.files?.[0];if(!file)return;if(file.size>6000000){saveMessage('6MB以下のJSONファイルを選んでください');return}try{$('saveText').value=await file.text();previewSaveText()}catch(e){saveMessage('ファイルを読めません：'+e.message)}}
function previewSaveText(){try{savePreview(decodeSave($('saveText').value),'JSONファイル')}catch(e){saveMessage('復元できません：'+e.message)}}
function previewBackup(index){let entry=validHistory()[index];if(entry)savePreview(entry.data,entry.reason)}
function savePreview(data,source){savePending={data:JSON.parse(JSON.stringify(data)),source};showSaveManager();}
function applyPendingSave(){if(!savePending)return;try{if(started)saveCheckpoint(encodeSave({p,floor}),'復元前の状態');else{let old=localStorage.getItem(SAVE_KEY);if(old){let valid=false;try{decodeSave(old);valid=true}catch{}if(valid)saveCheckpoint(old,'復元前の状態')}}let raw=encodeSave(savePending.data);localStorage.setItem(SAVE_KEY,raw);let data=decodeSave(raw);savePending=null;loadSaveData(data);say('セーブを復元しました')}catch(e){saveMessage('復元を中止しました：'+e.message)}}
function cancelSavePreview(){savePending=null;showSaveManager()}
function closeSaveManager(){savePending=null;saveMenuOpen=false;if(started)closePanel();else{$('card').classList.remove('framed-panel','wide');welcome()}}
function saveProgressLabel(data){let c=data.p.campaign;if(!c)return '旧版データ · Lv '+data.p.level;let rank=c.rank??Math.min(10,c.unlocked+1),region=REGIONS[c.region]?.name||'地域不明';return '冒険者ランク '+rank+' · Lv '+data.p.level+' · '+(c.inVillage?'灯火の村':region)}
function saveContractLabel(data){let q=data.p.campaign?.contract;if(!q)return '受注中の依頼なし';let name=SPECIES[q.target]?.name||'討伐対象';return name+' · '+(q.progress??(q.killed?1:0))+' / '+(q.required||1)+(q.killed?' · 報告待ち':'')}
function showSaveManager(message=''){saveMenuOpen=true;inventoryNav.open=false;padSettingsOpen=false;tutorialGuideOpen=false;padCursor.active=false;paused=true;keys={};held=false;leftDown=false;rightDown=false;route=[];$('modal').classList.remove('hidden');$('card').classList.add('wide');let history=validHistory(),h='<button class="close" onclick="closeSaveManager()">閉じる ×</button><label>SAVE / RECOVERY</label><h2>保存とバックアップ</h2><p id="saveMessage" role="status">'+gearEscape(message||saveLastError||'冒険者ランク・依頼の進行・装備・ジェム・回収済みの素材をこのブラウザーに保存します。')+'</p>';
 if(savePending){let d=savePending.data;h+='<div class="save-preview"><h3>復元するデータ</h3><p>'+gearEscape(saveProgressLabel(d))+'<br>'+gearEscape(saveContractLabel(d))+'<br>'+d.p.gold+' G · 鞄 '+d.p.bag.length+'個 · ジェム '+(d.p.gems?.length||0)+'個</p><p>現在の進行をこのデータへ戻します。現在の状態は復元前バックアップに残します。</p><button id="savePrimary" onclick="applyPendingSave()">このデータに復元</button> <button onclick="cancelSavePreview()">キャンセル</button></div>'}else{h+='<div class="save-actions"><button onclick="saveBackupNow()" '+(!started?'disabled':'')+'>今の状態をバックアップ</button><button onclick="exportSave()">JSONを書き出す</button></div><h3>直近のバックアップ（最大5件）</h3><div class="save-history">'+(history.length?history.map((e,i)=>'<button onclick="previewBackup('+i+')"><b>'+gearEscape(saveProgressLabel(e.data))+'</b><small>'+gearEscape(new Date(e.at).toLocaleString())+' / '+gearEscape(e.reason)+'</small></button>').join(''):'<p>まだバックアップはありません。プレイ中に自動で作成します。</p>')+'</div><details><summary>再開時の状態と保存先</summary><p>依頼の討伐数と報告待ちの状態を引き継ぎます。敵・落ちている未回収の素材・探索地図は再開時にリセットされます。Googleログインによるキャラクターの同期には対応していません。</p></details><h3>JSONから復元</h3><p>別のブラウザーへ移す場合は書き出したファイルを読み込みます。</p><input type="file" accept="application/json,.json" aria-label="セーブJSONファイル" onchange="readSaveFile(this)"><textarea id="saveText" aria-label="復元用JSON" placeholder="保存したJSONをここへ貼り付けることもできます"></textarea><button onclick="previewSaveText()">読み込み内容を確認</button><p class="muted">ブラウザーの保存データを消すと自動バックアップも消えます。大切なキャラクターはJSONで手元に保管してください。</p>'}$('card').innerHTML=h;frameMenu('save');$('savePrimary')?.focus()}
const protectedNewGame=newGame;newGame=type=>{let old=null;try{let raw=localStorage.getItem(SAVE_KEY);decodeSave(raw);old=raw}catch{}if(old){saveMenuOpen=true;inventoryNav.open=false;tutorialGuideOpen=false;paused=true;$('modal').classList.remove('hidden');$('card').innerHTML='<label>NEW CHARACTER</label><h2>新しい探索を始めますか？</h2><p>現在のキャラクターはバックアップに残し、新しいキャラクターを作成します。</p><button onclick="beginNewCharacter('+type+')">バックアップして開始</button> <button onclick="closeSaveManager()">戻る</button>';frameMenu('save');return}protectedNewGame(type)};
function beginNewCharacter(type){try{let old=localStorage.getItem(SAVE_KEY);if(old)saveCheckpoint(old,'新規開始前');saveMenuOpen=false;protectedNewGame(type)}catch(e){showSaveManager('新規開始を中止しました：'+e.message)}}
const savePadMenu=padMenu;padMenu=(g,left,right,dt)=>{if(saveMenuOpen&&(padEdge(g,'back')||padEdge(g,'pause'))){closeSaveManager();return}savePadMenu(g,left,right,dt)};
const savePanel=panel;panel=kind=>{saveMenuOpen=false;savePanel(kind);if(kind==='pause')$('card').querySelector('.panel-body')?.insertAdjacentHTML('beforeend','<button onclick="showSaveManager()">保存とバックアップ</button>')};
const saveWelcome=welcome;welcome=()=>{saveWelcome();$('card').insertAdjacentHTML('beforeend','<button onclick="showSaveManager()">保存とバックアップ</button>')};
const periodicSaveUpdate=update;update=dt=>{periodicSaveUpdate(dt);if(started&&!paused){saveTimer-=dt;if(saveTimer<=0){saveTimer=30;save()}}};
addEventListener('pagehide',()=>{if(started)save()});addEventListener('visibilitychange',()=>{if(document.hidden&&started)save()});
document.querySelector('.menu').insertAdjacentHTML('beforeend','<button id="saveBadge" onclick="showSaveManager()">保存</button>');if(!started)welcome();

const savedClosePanel=closePanel;closePanel=()=>{saveMenuOpen=false;savedClosePanel()};
